<script setup lang="ts">
import { computed,ref,watch } from 'vue'
import ExploreFrame from './ExploreFrame.vue'
import WorldSymbol from './WorldSymbol.vue'
import { useExperience } from './use-experience'
import { experiment,labObjects,pigments,type LabMission } from './science-lab'
const props=defineProps<{storageKey?:string}>()
const {save,frame,feedback,resetOpen,act,undo,requestReset,reset,hint}=useExperience(props,'science-lab')
const round=computed(()=>save.value.round),prediction=ref(''),tab=ref<LabMission['type']>('float'),object=ref(0),pair=ref([0,1]),result=ref<ReturnType<typeof experiment>>(null)
const rules=['选择浮沉、磁铁或混色实验；点实验卡可以准备对应的材料。','点击实验按钮，观察材料的位置和颜色变化，再读一读实验记录。','完成每张实验卡就结束这一轮；可以撤回，换材料再试，实验无需答题。']
const progress=computed(()=>round.value.missions.filter(mission=>round.value.done.includes(mission.id)).length)
function prepare(mission:LabMission){tab.value=mission.type;result.value=null;if(mission.type==='mix')pair.value=[...mission.pair];else object.value=mission.object;feedback.value='材料准备好了，点击按钮观察变化。'}
function run(){result.value=act(()=>experiment(round.value,tab.value,object.value,pair.value));if(result.value){feedback.value=(prediction.value?`你刚才猜“${prediction.value}”。现在看实际结果：`:'')+result.value.text;prediction.value=''}}
function name(mission:LabMission){return mission.type==='mix'?pigments[mission.pair[0]].name+'＋'+pigments[mission.pair[1]].name:(mission.type==='float'?'浮沉：':'磁铁：')+labObjects[mission.object].name}
function compare(){if(result.value && tab.value!=='mix'){tab.value=tab.value==='float'?'magnet':'float';result.value=null;prediction.value='';feedback.value='用同一份材料换一种实验，比较两种观察。'}}
function changeTab(type:LabMission['type']){tab.value=type;result.value=null}
watch(()=>[tab.value,object.value,pair.value.join(',')],()=>{prediction.value=''})
</script>
<template>
  <ExploreFrame v-bind="frame" :progress="`实验卡 ${progress} / ${round.missions.length}`" :rules="rules" @difficulty="requestReset" @undo="undo();result=null" @restart="requestReset()" @reset="reset();result=null" @cancel="resetOpen=false" @hint="hint('点击还没完成的实验卡，系统会准备对应材料；然后观察水中的位置、磁铁是否吸引，或颜料混合后的颜色。')">
    <div class="explore-toolbar"><button :class="{selected:tab==='float'}" @click="changeTab('float')">💧 浮沉实验</button><button :class="{selected:tab==='magnet'}" @click="changeTab('magnet')">🧲 磁铁实验</button><button :class="{selected:tab==='mix'}" @click="changeTab('mix')">🎨 颜色混合</button></div>
    <div v-if="tab==='float'" class="lab-scene lab-water"><span class="lab-water-line"></span><span class="lab-object" :class="{tested:result}" :style="{top:result?(result.floats?'32%':'75%'):'9%'}"><WorldSymbol :symbol="labObjects[object].icon" /></span><span class="lab-label">{{ result?(result.floats?'浮在水面':'沉到水底'):'材料准备好了' }}</span></div>
    <div v-else-if="tab==='magnet'" class="lab-scene lab-magnet"><span class="lab-magnet-icon">🧲</span><span class="lab-object" :style="{left:result?.magnetic?'41%':'75%',top:'42%'}"><WorldSymbol :symbol="labObjects[object].icon" /></span><span class="lab-label">{{ result?(result.magnetic?'被磁铁吸引':'保持原位，没有被吸引'):'把磁铁靠近材料试试' }}</span></div>
    <div v-else class="lab-scene lab-mix"><div class="lab-beakers"><span :style="{background:pigments[pair[0]].color}">{{ pigments[pair[0]].name }}</span><b>＋</b><span :style="{background:pigments[pair[1]].color}">{{ pigments[pair[1]].name }}</span><b>＝</b><span :style="{background:result?.color || '#e6e8dd'}">{{ result?'新颜色':'？' }}</span></div></div>
    <div v-if="tab!=='mix'" class="explore-cards lab-materials"><button v-for="(item,index) in labObjects" :key="item.id" :aria-label="'选择'+item.name" :class="['explore-card',{selected:object===index}]" :disabled="round.finished" @click="object=index;result=null"><span><WorldSymbol :symbol="item.icon" /></span>{{ item.name }}</button></div>
    <div v-else class="lab-pigments"><label v-for="index in [0,1]" :key="index">第 {{ index+1 }} 份颜料<select v-model.number="pair[index]" :disabled="round.finished" :aria-label="`第 ${index+1} 份颜料`" @change="result=null"><option v-for="(pigment,value) in pigments" :key="value" :value="value">{{ pigment.name }}</option></select></label></div>
    <div v-if="!result" class="explore-toolbar" aria-label="先猜一猜"><span>先猜一猜（可跳过）</span><button v-for="guess in tab==='float'?['会浮起','会下沉']:tab==='magnet'?['会被吸引','不会被吸引']:['橙色','紫色','绿色']" :key="guess" :aria-pressed="prediction===guess" :disabled="round.finished" @click="prediction=guess">{{ guess }}</button></div><div class="lab-run"><button :disabled="round.finished" class="explore-primary" @click="run">{{ tab==='float'?'放入水中':tab==='magnet'?'靠近磁铁':'混合颜料' }}</button><button v-if="result && tab!=='mix'" :disabled="round.finished" class="explore-secondary" @click="compare">同材料换一种实验</button></div>
    <h2 class="explore-subheading">今天的实验卡</h2><div class="lab-missions"><button v-for="mission in round.missions" :key="mission.id" :data-mission="mission.id" :disabled="round.finished" :class="{done:round.done.includes(mission.id)}" @click="prepare(mission)"><span>{{ round.done.includes(mission.id)?'✓':'○' }}</span>{{ name(mission) }}</button></div>
    <div v-if="round.journal.length" class="lab-journal" role="status" aria-label="实验记录"><h2>小小实验记录</h2><p v-for="entry in round.journal.slice(-3)" :key="entry.id">{{ entry.text }}</p></div>
  </ExploreFrame>
</template>
<style scoped>
.lab-scene{position:relative;height:230px;border:1px solid #d5e2d6;border-radius:17px;margin-bottom:20px;overflow:hidden;background:#f9fbf3}.lab-water{background:linear-gradient(#fafcf5 38%,#d4eaf0 38%,#b5d4df 100%)}.lab-water-line{position:absolute;left:0;right:0;top:38%;border-top:3px solid #a2c7d1}.lab-object{position:absolute;left:50%;transform:translate(-50%,-50%);font-size:46px;transition:top 1s ease,left 1s ease}.lab-label{position:absolute;left:0;right:0;bottom:13px;text-align:center;font-size:11px;color:#6b8990}.lab-magnet{background:linear-gradient(#eef1f8,#e4e8f0)}.lab-magnet-icon{position:absolute;top:32%;left:20%;font-size:65px}.lab-mix{display:flex;align-items:center;justify-content:center;padding:18px;background:#fcf8ed}.lab-beakers{display:flex;align-items:center;gap:15px}.lab-beakers>span{display:grid;place-items:center;width:80px;height:94px;border:4px solid #ffffff80;border-top:0;border-radius:0 0 15px 15px;color:#fff;font-size:12px;transition:background .5s}.lab-beakers b{font-size:20px;color:#9b967f}.lab-materials{margin-bottom:20px}.lab-materials button{font-size:11px;min-height:83px}.lab-pigments{display:flex;gap:14px;justify-content:center;flex-wrap:wrap;margin:22px 0}.lab-pigments label{display:flex;flex-direction:column;gap:8px;font-size:11px;color:#819174}.lab-pigments select{min-width:100px;padding:9px 14px;border:1px solid #d1dec5;border-radius:7px;background:#fff;color:#74826d}.lab-run{display:flex;justify-content:center;margin:20px 0}.lab-missions{display:flex;flex-wrap:wrap;gap:8px}.lab-missions button{padding:9px 11px;border:1px solid #dce5d0;background:#fff;border-radius:9px;font-size:11px;color:#8b977d}.lab-missions button>span{margin-right:7px}.lab-missions .done{background:#e1ecd6;border-color:#b8cba8;color:#63854e}.lab-journal{padding:20px;background:#fff9e9;border:1px solid #ebe0bc;border-radius:12px;margin-top:24px;font-size:12px;line-height:1.9;color:#928266}.lab-journal h2{font-size:14px;font-weight:650;margin-bottom:10px}.lab-journal p+p{margin-top:12px}@media(max-width:560px){.lab-scene{height:210px}.lab-beakers{gap:9px}.lab-beakers>span{width:55px;height:81px;font-size:10px}.lab-beakers b{font-size:16px}.lab-materials button{font-size:10px}.lab-journal{font-size:11px;padding:17px 14px}}@media(prefers-reduced-motion:reduce){.lab-object{transition:none}}
</style>
